from collections import deque

class Stack:
    """基于 deque 的栈实现(比 list 在头部插入更优, 这里仅尾部操作两者等效)。"""
    def __init__(self):
        self._data = deque()

    def push(self, x):
        self._data.append(x)

    def pop(self):
        return self._data.pop()

    def top(self):
        return self._data[-1]

    def empty(self):
        return len(self._data) == 0

    def size(self):
        return len(self._data)


def bracket_match(s):
    """括号匹配: 检查字符串中的括号是否正确配对。
    支持: () [] {}
    """
    pairs = {')': '(', ']': '[', '}': '{'}
    st = Stack()
    for ch in s:
        if ch in '([{':
            st.push(ch)
        elif ch in ')]}':
            if st.empty() or st.pop() != pairs[ch]:
                return False
    return st.empty()


def evaluate_rpn(tokens):
    """逆波兰表达式求值(后缀表达式)。
    示例: ['2','1','+','3','*'] => (2+1)*3 = 9
    """
    st = Stack()
    for tok in tokens:
        if tok in '+-*/':
            b = st.pop()
            a = st.pop()
            if tok == '+':
                st.push(a + b)
            elif tok == '-':
                st.push(a - b)
            elif tok == '*':
                st.push(a * b)
            elif tok == '/':
                st.push(int(a / b))  # 向零取整(竞赛惯例)
        else:
            st.push(int(tok))
    return st.pop()


if __name__ == '__main__':
    # 测试栈基本操作
    st = Stack()
    for i in range(5):
        st.push(i)
    print(f'Stack size: {st.size()}')  # 5
    print(f'Top: {st.top()}')  # 4
    while not st.empty():
        print(st.pop(), end=' ')  # 4 3 2 1 0
    print()

    # 测试括号匹配
    assert bracket_match('(a[b]{c})') == True
    assert bracket_match('([)]') == False
    assert bracket_match('(((') == False
    assert bracket_match('') == True
    print('Bracket match: all tests passed')

    # 测试逆波兰表达式
    assert evaluate_rpn(['2', '1', '+', '3', '*']) == 9
    assert evaluate_rpn(['4', '13', '5', '/', '+']) == 6  # 4 + (13/5=2) = 6
    assert evaluate_rpn(['18']) == 18  # 单个操作数
    print('RPN evaluate: all tests passed')
